struct Harness{
 using Dict=CefRefPtr<CefDictionaryValue>;struct Call{std::string method;Dict params;SuiteCutQueryNodeTransfer::Result done;};
 std::deque<Call>calls;std::string error,delivered;bool current=true;size_t describes=0,resolves=0;
 void Start(){SuiteCutQueryNodeTransfer::Transfer([this](const std::string&method,Dict params,SuiteCutQueryNodeTransfer::Result done){calls.push_back({method,params->Copy(false),std::move(done)});},[this]{return current;},[this](const std::string&cause){error=cause;},"actual-private-source-array",42,"actual-owner-group",[this](const std::string&array){delivered=array;});}
 Call Take(const std::string&method){assert(!calls.empty());auto call=std::move(calls.front());calls.pop_front();assert(call.method==method);return call;}
 static std::string JSON(Dict value){auto out=CefValue::Create();out->SetDictionary(value);return CefWriteJSON(out,JSON_WRITER_DEFAULT).ToString();}
 void Properties(size_t count=128){auto call=Take("Runtime.getProperties");assert(call.params->GetString("objectId")=="actual-private-source-array");auto result=CefDictionaryValue::Create();auto fields=CefListValue::Create();for(size_t i=0;i<count;++i){auto field=CefDictionaryValue::Create();field->SetString("name",std::to_string(i));auto node=CefDictionaryValue::Create();node->SetString("type","object");node->SetString("subtype","node");node->SetString("objectId","selected-"+std::to_string(i));field->SetDictionary("value",node);fields->SetDictionary(i,field);}result->SetList("result",fields);call.done(true,JSON(result));}
 static Dict Deep(size_t count=128){auto result=CefDictionaryValue::Create();auto remote=CefDictionaryValue::Create();remote->SetString("subtype","array");auto deep=CefDictionaryValue::Create();deep->SetString("type","array");auto nodes=CefListValue::Create();for(size_t i=0;i<count;++i){auto node=CefDictionaryValue::Create();node->SetString("type","node");auto value=CefDictionaryValue::Create();value->SetInt("backendNodeId",2000+static_cast<int>(i));value->SetInt("nodeType",1);auto attrs=CefDictionaryValue::Create();attrs->SetString("__suitecutNativeUTF16Scalar","d800");value->SetDictionary("attributes",attrs);node->SetDictionary("value",value);nodes->SetDictionary(i,node);}deep->SetList("value",nodes);remote->SetDictionary("deepSerializedValue",deep);result->SetDictionary("result",remote);return result;}
 Call Metadata(){auto call=Take("Runtime.callFunctionOn");assert(call.params->GetString("objectId")=="actual-private-source-array"&&call.params->GetString("functionDeclaration")=="function(){return this;}");auto options=call.params->GetDictionary("serializationOptions");assert(options&&options->GetString("serialization")=="deep"&&options->GetInt("maxDepth")==1&&options->GetDictionary("additionalParameters")->GetInt("maxNodeDepth")==0);return call;}
 void Fill(bool deep,size_t count=128,int duplicate=-1){auto array=Take("Runtime.evaluate");assert(array.params->GetInt("contextId")==42&&array.params->GetString("objectGroup")=="actual-owner-group");array.done(true,"{\"result\":{\"objectId\":\"actual-main-array\"}}");for(size_t i=0;i<count;++i){if(!deep){auto describe=Take("DOM.describeNode");++describes;assert(describe.params->GetString("objectId")=="selected-"+std::to_string(i));describe.done(true,"{\"node\":{\"backendNodeId\":"+std::to_string(6000+i)+"}}");}auto resolve=Take("DOM.resolveNode");++resolves;const int expected=deep?2000+static_cast<int>(i==count-1&&duplicate>=0?duplicate:i):6000+static_cast<int>(i);assert(resolve.params->GetInt("backendNodeId")==expected&&resolve.params->GetInt("executionContextId")==42&&resolve.params->GetString("objectGroup")=="actual-owner-group");resolve.done(true,"{\"object\":{\"subtype\":\"node\",\"objectId\":\"main-"+std::to_string(i)+"\"}}");if((i+1)%128==0||i+1==count){auto append=Take("Runtime.callFunctionOn");auto args=append.params->GetList("arguments");const size_t offset=i/128*128;assert(args);assert(args->GetDictionary(0)->GetInt("value")==static_cast<int>(offset)&&args->GetSize()==i-offset+2);for(size_t j=offset;j<=i;++j)assert(args->GetDictionary(j-offset+1)->GetString("objectId")=="main-"+std::to_string(j));append.done(true,"{}");}}assert(error.empty()&&delivered=="actual-main-array"&&calls.empty());}
};
