 {Harness h;h.Start();h.Properties(129);auto metadata=h.Metadata();metadata.done(true,Harness::JSON(Harness::Deep(129)));h.Fill(true,129);assert(h.describes==0&&h.resolves==129);}
 {Harness h;h.Start();h.Properties();auto metadata=h.Metadata();auto result=Harness::Deep();auto nodes=result->GetDictionary("result")->GetDictionary("deepSerializedValue")->GetList("value");nodes->GetDictionary(42)->SetInt("weakLocalObjectReference",0);auto last=CefDictionaryValue::Create();last->SetString("type","node");last->SetInt("weakLocalObjectReference",0);nodes->SetDictionary(127,last);metadata.done(true,Harness::JSON(result));h.Fill(true,128,42);}
 for(const std::string kind:{"type","backend","nodeType","count","unknown-reference","reference-type","inconsistent-reference","object-value"}){Harness h;h.Start();h.Properties();auto metadata=h.Metadata();auto result=Harness::Deep();auto nodes=result->GetDictionary("result")->GetDictionary("deepSerializedValue")->GetList("value");auto last=nodes->GetDictionary(127);if(kind=="type")last->SetString("type","object");else if(kind=="backend")last->GetDictionary("value")->SetString("backendNodeId","2127");else if(kind=="nodeType")last->GetDictionary("value")->SetInt("nodeType",0);else if(kind=="count")nodes->Remove(127);else if(kind=="unknown-reference"){last->Remove("value");last->SetInt("weakLocalObjectReference",777);}else if(kind=="reference-type")last->SetString("weakLocalObjectReference","0");else if(kind=="object-value"){last->SetString("value","author-shaped");last->SetInt("weakLocalObjectReference",0);}else{nodes->GetDictionary(0)->SetInt("weakLocalObjectReference",7);last->SetInt("weakLocalObjectReference",7);}metadata.done(true,Harness::JSON(result));h.Fill(false);assert(h.describes==128);}
 {Harness h;h.Start();h.Properties();h.Metadata().done(false,"{\"message\":\"Actual browser does not support deep metadata\"}");h.Fill(false);}
 {Harness h;h.Start();h.Properties();auto call=h.Metadata();h.current=false;call.done(true,Harness::JSON(Harness::Deep()));assert(h.calls.empty()&&h.delivered.empty()&&!h.error.empty());}
 {Harness h;h.Start();h.Properties();auto call=h.Metadata();call.done(true,Harness::JSON(Harness::Deep()));auto create=h.Take("Runtime.evaluate");h.current=false;create.done(true,"{\"result\":{\"objectId\":\"late-array\"}}");assert(h.calls.empty()&&h.delivered.empty()&&!h.error.empty());}
 {Harness h;h.Start();h.Properties();auto call=h.Metadata();call.done(true,Harness::JSON(Harness::Deep()));auto create=h.Take("Runtime.evaluate");create.done(true,"{\"result\":{\"objectId\":\"actual-main-array\"}}");auto resolve=h.Take("DOM.resolveNode");resolve.done(true,"{\"object\":{\"subtype\":\"object\",\"objectId\":\"fake-author-object\"}}");assert(h.calls.empty()&&h.delivered.empty()&&!h.error.empty());}
 std::cout<<"PASS9 deep native node metadata/cohort identities/ordered actual backend adoption,128 batching,weak references,author-attribute noninterpretation,all-invalid metadata exact-node fallback andlate-epoch rejection\n";
